#!/bin/bash
# The planted defects near #930's change at the lane's head: 29 existing ones and the five Listener copy defects,
# at two interfaces (each at its own entity) and one (1x1/1if), and the five at 8x8/1if.
cd /data-2/milan/lanes/894-8x8 && echo "head $(git rev-parse HEAD), $(git status --porcelain | wc -l) changed path(s)"
for n in 2 1; do echo "== interfaces $n"; rm -rf /data-2/milan/tmp/894b-a781/r10/dev/q$n; python3 -B /data-2/milan/tmp/894b-a781/r10/dev_mut.py /data-2/milan/tmp/894b-a781/r10/dev/q$n $n - attribute-change-uncounted binding-change-not-copied failed-listener-ready feedback-change-clears-both-kinds feedback-identity-copy-stale feedback-intrapdu-lost feedback-withdrawal-overwritten four-way-f3b-asking-failed-excluded four-way-f3b-listener-not-forwarded four-way-f3b-withdrawal-stale no-retry-after-a-change own-listener-declaration-not-copied own-talker-declaration-not-copied p11-postwithdrawal-kind-overwrite p11-reset-withdrawal-lost ready-before-vlan reclaim-forgotten-while-owed refusal-moves-unrecorded refusal-returns-unrecorded reset-keeps-listener-present retry-without-a-change shared-identity-overwritten shared-ready-uses-first-vlan snapshot-walks-once talker-change-while-valid-unmarked transmit-binding-holds-a-build transmit-walk-holds-nothing unchanged-deadline-unchecked unchanged-record-walks listener-copy-* | grep "^defects\|^\[ok\]\|^\[ESC\|CAUGHT\|FAILED"; done
echo "== 8x8/1if"; rm -rf /data-2/milan/tmp/894b-a781/r10/dev/q8; python3 -B /data-2/milan/tmp/894b-a781/r10/dev_mut.py /data-2/milan/tmp/894b-a781/r10/dev/q8 1 endstation_ax7101_8x8 'listener-copy-*' | grep "^defects\|^\[ok\]\|^\[ESC\|CAUGHT\|FAILED"
